// Search the knowledge base for content relevant to a query
export function searchKB(query) {
  const q = query.toLowerCase();
  const results = [];

  // Check for PA code mentions (e.g. "CAR 5.1", "MPM", "RDM 3.2")
  const practiceMatch = query.match(/([A-Z]{2,4})\s+(\d+\.\d+)/g) || [];
  const paMatch = query.match(/\b(CAR|CM|DAR|EST|GOV|II|MC|MPM|OPD|OPM|PAD|PCM|PR|RDM|RSK|SAM|TS|VV|PLAN|OT)\b/g) || [];

  // Direct practice lookup
  for (const pm of practiceMatch) {
    const [code, num] = pm.split(/\s+/);
    const pid = `${code} ${num}`;
    const paData = CMMI_KB.practice_areas[code];
    if (paData && paData.practices[pid]) {
      results.push({ type: 'practice', code, pid, data: paData.practices[pid] });
    }
  }

  // PA-level lookup
  for (const code of paMatch) {
    if (CMMI_KB.practice_areas[code] && !practiceMatch.length) {
      results.push({ type: 'pa', code, data: CMMI_KB.practice_areas[code] });
    }
  }

  // Keyword search across all practices
  if (results.length === 0) {
    for (const [code, pa] of Object.entries(CMMI_KB.practice_areas)) {
      let paScore = 0;
      if (pa.intent && pa.intent.toLowerCase().includes(q.substring(0,20))) paScore += 3;
      if (pa.intro && pa.intro.toLowerCase().includes(q.substring(0,20))) paScore += 2;
      
      const matchingPractices = [];
      for (const [pid, p] of Object.entries(pa.practices)) {
        const text = `${p.statement} ${p.value} ${p.explanation}`.toLowerCase();
        if (q.split(' ').some(word => word.length > 4 && text.includes(word))) {
          matchingPractices.push({ pid, data: p });
          paScore += 1;
        }
      }
      if (paScore > 0) results.push({ type: 'keyword', code, score: paScore, pa, matchingPractices });
    }
    results.sort((a, b) => (b.score || 0) - (a.score || 0));
  }

  return results.slice(0, 5);
}

export function formatKBResponse(query, results) {
  if (results.length === 0) return null;

  let response = '';

  for (const r of results) {
    if (r.type === 'practice') {
      const p = r.data;
      response += `**${r.pid} — from CMMI V3.0 Model**\n\n`;
      if (p.statement) response += `**Practice Statement:**\n${p.statement}\n\n`;
      if (p.value) response += `**Value:**\n${p.value}\n\n`;
      if (p.explanation) response += `**Further Explanation:**\n${p.explanation}\n\n`;
    } else if (r.type === 'pa') {
      const pa = r.data;
      response += `**${r.code} — ${pa.intent ? 'Intent: ' + pa.intent : ''}**\n\n`;
      if (pa.intro) response += `${pa.intro}\n\n`;
      if (Object.keys(pa.practices).length > 0) {
        response += `**Practice Summary:**\n`;
        for (const [pid, p] of Object.entries(pa.practices)) {
          response += `• **${pid}**: ${p.statement.substring(0,120)}...\n`;
        }
      }
    } else if (r.type === 'keyword') {
      if (r.matchingPractices.length > 0) {
        response += `**${r.code}** — ${r.pa.intent || ''}\n`;
        for (const { pid, data } of r.matchingPractices.slice(0, 3)) {
          response += `\n• **${pid}**: ${data.statement.substring(0,200)}`;
          if (data.value) response += `\n  *Value: ${data.value.substring(0,150)}*`;
          response += '\n';
        }
        response += '\n';
      }
    }
  }

  return response.trim() || null;
}
